import { NextResponse } from "next/server";
import { signUpWithPassword } from "@/platform/persistence/supabase-rest";
import { setStoryAuthCookies } from "@/platform/identity/cookies";

export const runtime = "nodejs";

export async function POST(request: Request) {
  try {
    const body = await request.json() as { email?: string; password?: string; displayName?: string; termsAccepted?: boolean; privacyAccepted?: boolean };
    if (!body.termsAccepted || !body.privacyAccepted) return NextResponse.json({ error: "Accept the Terms and Privacy Policy to create an account." }, { status: 400 });
    const origin = (process.env.NEXT_PUBLIC_SITE_URL ?? new URL(request.url).origin).replace(/\/$/, "");
    const session = await signUpWithPassword(body.email ?? "", body.password ?? "", body.displayName ?? "", `${origin}/login?verified=1`);
    const response = NextResponse.json({ registered: true, verificationRequired: !session.access_token });
    return session.access_token ? setStoryAuthCookies(response, session) : response;
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not create account.";
    const status = /not configured/i.test(message) ? 503 : 400;
    return NextResponse.json({ error: message }, { status });
  }
}

import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { updateSupabasePassword } from "@/platform/persistence/supabase-rest";

export const runtime = "nodejs";

export async function POST(request: Request) {
  try {
    const session = await requireStorySession();
    const { password } = await request.json() as { password?: string };
    await updateSupabasePassword(session.token, password ?? "");
    return NextResponse.json({ updated: true });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not update password.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Your reset session has expired. Request another recovery email." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { createSubscriptionCheckout } from "@/platform/billing/stripe-subscriptions";
import { isPlanSlug, type BillingInterval } from "@/platform/billing/plans";

export const runtime = "nodejs";

function releaseOrigin(request: Request) {
  if (process.env.VERCEL_ENV === "preview") return new URL(request.url).origin;
  return (process.env.NEXT_PUBLIC_SITE_URL || new URL(request.url).origin).replace(/\/$/, "");
}

export async function POST(request: Request) {
  try {
    const session = await requireStorySession();
    const body = await request.json() as { plan?: unknown; interval?: unknown };
    if (!isPlanSlug(body.plan) || body.plan === "free") return NextResponse.json({ error: "Choose a paid plan." }, { status: 400 });
    const interval: BillingInterval | null = body.interval === "month" || body.interval === "year" ? body.interval : null;
    if (!interval) return NextResponse.json({ error: "Choose monthly or annual billing." }, { status: 400 });
    const checkout = await createSubscriptionCheckout({ userId: session.user.id, email: session.user.email, plan: body.plan, interval, origin: releaseOrigin(request) });
    if (!checkout.url) throw new Error("Stripe did not return a Checkout URL.");
    return NextResponse.json({ checkoutUrl: checkout.url, sessionId: checkout.id });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not start subscription checkout.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

