import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { getUserSubscription } from "@/platform/billing/subscription";
import { planCatalog } from "@/platform/billing/plans";
import { supabaseRest } from "@/platform/persistence/supabase-rest";

export const runtime = "nodejs";

export async function GET() {
  try {
    const session = await requireStorySession();
    const subscription = await getUserSubscription(session.user.id, session.token);
    const media = await supabaseRest<Array<{ size_bytes: number | null }>>("media_assets?select=size_bytes&limit=5000", session.token);
    const storageBytes = media.reduce((sum, row) => sum + Number(row.size_bytes ?? 0), 0);
    return NextResponse.json({ subscription, plan: planCatalog[subscription.plan_slug], usage: { storageBytes } });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not load subscription.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

import { NextResponse } from "next/server";
import { createPremiumCheckout } from "@/platform/billing/stripe-rest";

export const runtime = "nodejs";

export async function POST(request: Request) {
  try {
    const body = await request.json() as { mode?: string };
    const origin = process.env.NEXT_PUBLIC_SITE_URL ?? new URL(request.url).origin;
    const session = await createPremiumCheckout(origin.replace(/\/$/, ""), body.mode ?? "friends");
    if (!session.url) return NextResponse.json({ error: "Stripe did not return a Checkout URL." }, { status: 502 });
    return NextResponse.json({ url: session.url });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Checkout is unavailable.";
    const status = /not configured/i.test(message) ? 503 : 400;
    return NextResponse.json({ error: message }, { status });
  }
}

import { NextResponse } from "next/server";
import { createEntitlementToken, verifyEntitlementToken } from "@/platform/entitlements/token";
import { retrieveCheckoutSession } from "@/platform/billing/stripe-rest";

export const runtime = "nodejs";

export async function GET(request: Request) {
  try {
    const sessionId = new URL(request.url).searchParams.get("session_id");
    if (!sessionId) return NextResponse.json({ error: "Missing Checkout Session id." }, { status: 400 });
    const session = await retrieveCheckoutSession(sessionId);
    if (session.status !== "complete" || session.payment_status !== "paid" || session.metadata?.entitlement !== "threadtales-premium") {
      return NextResponse.json({ error: "This purchase is not a completed paid ThreadTales Premium session." }, { status: 403 });
    }
    const token = createEntitlementToken(session.id);
    return NextResponse.json({ token, product: "threadtales-premium", expiresInDays: 365 });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not recover this purchase.";
    return NextResponse.json({ error: message }, { status: /not configured/i.test(message) ? 503 : 400 });
  }
}

export async function POST(request: Request) {
  try {
    const body = await request.json() as { token?: string };
    if (!body.token) return NextResponse.json({ valid: false }, { status: 400 });
    const entitlement = verifyEntitlementToken(body.token);
    return NextResponse.json({ valid: Boolean(entitlement), entitlement });
  } catch {
    return NextResponse.json({ valid: false }, { status: 400 });
  }
}

import { NextResponse } from "next/server";
import { getStoryEnrichmentProvider } from "@/platform/ai/openai-provider";
import { isSupabaseConfigured, isSupabaseServerConfigured } from "@/platform/persistence/config";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const subscriptionPriceKeys = [
  "STRIPE_PRICE_PLUS_MONTHLY","STRIPE_PRICE_PLUS_ANNUAL",
  "STRIPE_PRICE_FAMILY_MONTHLY","STRIPE_PRICE_FAMILY_ANNUAL",
  "STRIPE_PRICE_CREATOR_MONTHLY","STRIPE_PRICE_CREATOR_ANNUAL",
  "STRIPE_PRICE_BUSINESS_MONTHLY","STRIPE_PRICE_BUSINESS_ANNUAL",
] as const;

export async function GET() {
  const provider = getStoryEnrichmentProvider();
  const supabasePublic = isSupabaseConfigured();
  const supabaseServer = isSupabaseServerConfigured();
  const externalTelemetry = Boolean(process.env.TELEMETRY_ENDPOINT);
  return NextResponse.json({
    stripe: {
      checkout: Boolean(process.env.STRIPE_SECRET_KEY && process.env.STRIPE_PRICE_THREADTALES_PREMIUM && process.env.ENTITLEMENT_SIGNING_SECRET),
      webhook: Boolean(process.env.STRIPE_WEBHOOK_SECRET),
      subscriptions: Boolean(process.env.STRIPE_SECRET_KEY && subscriptionPriceKeys.every((key) => Boolean(process.env[key]))),
    },
    supabase: { public: supabasePublic, server: supabaseServer, auth: supabasePublic, storage: supabaseServer },
    ai: { enabled: Boolean(provider), provider: provider?.name ?? null },
    telemetry: { enabled: externalTelemetry || supabaseServer, sink: externalTelemetry ? "external" : supabaseServer ? "supabase" : null },
  }, { headers: { "Cache-Control": "no-store" } });
}

import { NextResponse } from "next/server";
import { createPremiumCheckout } from "@/platform/billing/stripe-rest";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET(request: Request) {
  if (process.env.VERCEL_ENV !== "preview") {
    return NextResponse.json({ error: "Not found." }, { status: 404 });
  }

  const secret = process.env.STRIPE_SECRET_KEY;
  if (!secret?.startsWith("sk_test_")) {
    return NextResponse.json(
      { error: "Preview Stripe test secret is not configured." },
      { status: 503, headers: { "Cache-Control": "no-store" } },
    );
  }

  if (!process.env.STRIPE_PRICE_THREADTALES_PREMIUM) {
    return NextResponse.json(
      { error: "Preview Stripe price is not configured." },
      { status: 503, headers: { "Cache-Control": "no-store" } },
    );
  }

  try {
    const origin = new URL(request.url).origin;
    const session = await createPremiumCheckout(origin, "friends");
    return NextResponse.json(
      {
        ok: true,
        sessionId: session.id,
        hasCheckoutUrl: Boolean(session.url),
        environment: "preview-test",
      },
      { headers: { "Cache-Control": "no-store" } },
    );
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Stripe preview smoke failed.";
    return NextResponse.json(
      { error: message },
      { status: /not configured/i.test(message) ? 503 : 502, headers: { "Cache-Control": "no-store" } },
    );
  }
}

import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { supabaseRest, supabaseStorageDelete } from "@/platform/persistence/supabase-rest";

export const runtime = "nodejs";

export async function DELETE(_: Request, context: { params: Promise<{ id: string }> }) {
  try {
    const session = await requireStorySession();
    const { id } = await context.params;
    if (!/^[0-9a-f-]{36}$/i.test(id)) return NextResponse.json({ error: "Invalid media id." }, { status: 400 });
    const rows = await supabaseRest<{ id: string; object_path: string }[]>(`media_assets?id=eq.${id}&select=id,object_path`, session.token);
    if (!rows[0]) return NextResponse.json({ error: "Media not found." }, { status: 404 });
    await supabaseStorageDelete(rows[0].object_path, session.token);
    await supabaseRest<null>(`media_assets?id=eq.${id}`, session.token, { method: "DELETE", headers: { Prefer: "return=minimal" } });
    return NextResponse.json({ deleted: true });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not delete media.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

import { randomUUID } from "node:crypto";
import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { supabaseRest, supabaseStorageSignedUrl, supabaseStorageUpload } from "@/platform/persistence/supabase-rest";
import { getUserSubscription } from "@/platform/billing/subscription";
import { planCatalog } from "@/platform/billing/plans";

export const runtime = "nodejs";

const allowedMime = new Map([
  ["image/jpeg", { kind: "image", ext: "jpg" }],
  ["image/png", { kind: "image", ext: "png" }],
  ["image/webp", { kind: "image", ext: "webp" }],
  ["video/mp4", { kind: "video", ext: "mp4" }],
  ["video/webm", { kind: "video", ext: "webm" }],
  ["audio/mpeg", { kind: "audio", ext: "mp3" }],
  ["audio/mp4", { kind: "audio", ext: "m4a" }],
  ["audio/wav", { kind: "audio", ext: "wav" }],
  ["application/pdf", { kind: "document", ext: "pdf" }],
]);

type MediaRow = { id: string; user_id: string; world_id: string | null; object_path: string; mime_type: string | null; size_bytes: number | null; media_kind: string; caption?: string | null; occurred_at?: string | null; place?: string | null; created_at: string };

export async function GET(request: Request) {
  try {
    const session = await requireStorySession();
    const url = new URL(request.url);
    const world = url.searchParams.get("world");
    const filter = world && /^[0-9a-f-]{36}$/i.test(world) ? `&world_id=eq.${world}` : "";
    const rows = await supabaseRest<MediaRow[]>(`media_assets?select=id,user_id,world_id,object_path,mime_type,size_bytes,media_kind,caption,occurred_at,place,created_at${filter}&order=created_at.desc&limit=100`, session.token);
    const media = await Promise.all(rows.map(async (row) => ({ ...row, signedUrl: await supabaseStorageSignedUrl(row.object_path, session.token).catch(() => null) })));
    return NextResponse.json({ media });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not load media.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

export async function POST(request: Request) {
  try {
    const session = await requireStorySession();
    const subscription = await getUserSubscription(session.user.id, session.token).catch(() => ({ plan_slug: "free" as const, status: "free" }));
    const limits = planCatalog[subscription.plan_slug];
    const form = await request.formData();
    const upload = form.get("file");
    if (!(upload instanceof File)) return NextResponse.json({ error: "Choose a file to upload." }, { status: 400 });
    const type = allowedMime.get(upload.type);
    if (!type) return NextResponse.json({ error: "Unsupported file type." }, { status: 415 });
    if (upload.size <= 0 || upload.size > limits.maxUploadBytes) return NextResponse.json({ error: `Your ${limits.label} plan supports files up to ${Math.round(limits.maxUploadBytes / 1024 / 1024)} MB.` }, { status: 413 });
    const worldId = String(form.get("worldId") ?? "");
    const validWorld = /^[0-9a-f-]{36}$/i.test(worldId) ? worldId : null;
    if (validWorld) {
      const worlds = await supabaseRest<{ id: string }[]>(`worlds?id=eq.${validWorld}&select=id`, session.token);
      if (!worlds[0]) return NextResponse.json({ error: "World not found." }, { status: 404 });
    }
    const current = await supabaseRest<{ size_bytes: number | null }[]>("media_assets?select=size_bytes&limit=5000", session.token);
    const currentBytes = current.reduce((sum, item) => sum + Number(item.size_bytes ?? 0), 0);
    if (currentBytes + upload.size > limits.storageBytes) return NextResponse.json({ error: `${limits.label} storage quota reached. Remove media or change plan before uploading more.` }, { status: 409 });
    const path = `${session.user.id}/${validWorld ?? "library"}/${randomUUID()}.${type.ext}`;
    await supabaseStorageUpload(path, upload, session.token, upload.type);
    const payload = {
      user_id: session.user.id,
      world_id: validWorld,
      object_path: path,
      mime_type: upload.type,
      size_bytes: upload.size,
      media_kind: type.kind,
      caption: String(form.get("caption") ?? "").trim().slice(0, 500) || null,
      place: String(form.get("place") ?? "").trim().slice(0, 160) || null,
      occurred_at: String(form.get("occurredAt") ?? "") || null,
    };
    try {
      const rows = await supabaseRest<MediaRow[]>("media_assets", session.token, { method: "POST", headers: { Prefer: "return=representation" }, body: JSON.stringify(payload) });
      const row = rows[0];
      const signedUrl = row ? await supabaseStorageSignedUrl(row.object_path, session.token).catch(() => null) : null;
      return NextResponse.json({ media: row ? { ...row, signedUrl } : null }, { status: 201 });
    } catch (error) {
      // The object is private and inaccessible to other users; metadata failure is surfaced for cleanup instead of hidden.
      throw error;
    }
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not upload media.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { supabaseRest } from "@/platform/persistence/supabase-rest";

export const runtime = "nodejs";

type Track = { id: string; owner_id: string; title: string; artist: string; album?: string | null; artwork_media_id?: string | null; external_url?: string | null; provider: string; memory_date?: string | null; note?: string | null; created_at: string };

export async function GET() {
  try {
    const session = await requireStorySession();
    const tracks = await supabaseRest<Track[]>("music_tracks?select=*&order=created_at.desc&limit=200", session.token);
    return NextResponse.json({ tracks });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not load soundtrack.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

export async function POST(request: Request) {
  try {
    const session = await requireStorySession();
    const body = await request.json() as { title?: unknown; artist?: unknown; album?: unknown; artworkMediaId?: unknown; externalUrl?: unknown; memoryDate?: unknown; note?: unknown };
    const title = typeof body.title === "string" ? body.title.trim().slice(0, 160) : "";
    const artist = typeof body.artist === "string" ? body.artist.trim().slice(0, 160) : "";
    if (!title || !artist) return NextResponse.json({ error: "Song title and artist are required." }, { status: 400 });
    let externalUrl: string | null = null;
    if (typeof body.externalUrl === "string" && body.externalUrl.trim()) {
      try { const parsed = new URL(body.externalUrl.trim()); if (parsed.protocol !== "https:") throw new Error(); externalUrl = parsed.toString().slice(0, 1000); } catch { return NextResponse.json({ error: "Song link must be a valid HTTPS URL." }, { status: 400 }); }
    }
    const artwork = typeof body.artworkMediaId === "string" && /^[0-9a-f-]{36}$/i.test(body.artworkMediaId) ? body.artworkMediaId : null;
    const payload = { owner_id: session.user.id, title, artist, album: typeof body.album === "string" ? body.album.trim().slice(0, 160) || null : null, artwork_media_id: artwork, external_url: externalUrl, provider: "manual", memory_date: typeof body.memoryDate === "string" && /^\d{4}-\d{2}-\d{2}$/.test(body.memoryDate) ? body.memoryDate : null, note: typeof body.note === "string" ? body.note.trim().slice(0, 500) || null : null };
    const rows = await supabaseRest<Track[]>("music_tracks", session.token, { method: "POST", headers: { Prefer: "return=representation" }, body: JSON.stringify(payload) });
    return NextResponse.json({ track: rows[0] }, { status: 201 });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not add song.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

export async function DELETE(request: Request) {
  try {
    const session = await requireStorySession();
    const id = new URL(request.url).searchParams.get("id") ?? "";
    if (!/^[0-9a-f-]{36}$/i.test(id)) return NextResponse.json({ error: "Invalid track id." }, { status: 400 });
    await supabaseRest<null>(`music_tracks?id=eq.${id}`, session.token, { method: "DELETE", headers: { Prefer: "return=minimal" } });
    return NextResponse.json({ deleted: true });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not remove song.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}
